rawInput.content:
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task gets [x] prefix and preserves name', () => {
  assert.equal(taskLabel('publish release', true), '[x] publish release');
});

test('incomplete task keeps [ ] prefix and preserves name', () => {
  assert.equal(taskLabel('publish release', false), '[ ] publish release');
});

test('completed task preserves empty or whitespace name exactly', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('  trimmed? no  ', true), '[x]   trimmed? no  ');
});

test('incomplete task preserves empty or whitespace name exactly', () => {
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('  trimmed? no  ', false), '[ ]   trimmed? no  ');
});

