import assert from 'node:assert/strict';
import {test} from 'node:test';
import {taskLabel} from '../src/labels.ts';

test('completed task prefixes with [x]', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
  assert.equal(taskLabel('finish report', true), '[x] finish report');
});

test('incomplete task prefixes with [ ]', () => {
  assert.equal(taskLabel('draft', false), '[ ] draft');
  assert.equal(taskLabel('finish report', false), '[ ] finish report');
});

test('preserves name formatting and whitespace exactly', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('  spaced  ', true), '[x]   spaced  ');
  assert.equal(taskLabel('Task #123 (urgent!)', true), '[x] Task #123 (urgent!)');
});

