import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Regression tests: async route error forwarding and handling', () => {
  const router = makeRouter();

  const createMockRes = () => {
    const sent = [];
    return {
      sent,
      send(val) {
        sent.push(val);
        return val;
      }
    };
  };

  const createMockNext = () => {
    const errors = [];
    const next = (err) => {
      errors.push(err);
    };
    next.errors = errors;
    return next;
  };

  test('router registration order and methods are preserved', () => {
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' }
      ]
    );
  });

  test('GET /accounts/:id succeeds and returns response value', async () => {
    const route = router.routes[0];
    const res = createMockRes();
    const next = createMockNext();
    const result = await route.handler({ id: '123' }, res, next);
    assert.equal(result, 'account:123');
    assert.deepEqual(res.sent, ['account:123']);
    assert.equal(next.errors.length, 0);
  });

  test('GET /accounts/:id forwards failure to next', async () => {
    const route = router.routes[0];
    const res = createMockRes();
    const next = createMockNext();
    await route.handler({ id: '123', fail: true }, res, next);
    assert.equal(next.errors.length, 1);
    assert.equal(next.errors[0]?.message, 'account read');
    assert.deepEqual(res.sent, []);
  });

  test('POST /accounts (named async function) succeeds and returns response value', async () => {
    const route = router.routes[1];
    const res = createMockRes();
    const next = createMockNext();
    const result = await route.handler({ id: 'acc-new' }, res, next);
    assert.equal(result, 'created:acc-new');
    assert.deepEqual(res.sent, ['created:acc-new']);
    assert.equal(next.errors.length, 0);
  });

  test('POST /accounts (named async function) forwards failure to next', async () => {
    const route = router.routes[1];
    const res = createMockRes();
    const next = createMockNext();
    await route.handler({ id: 'acc-new', fail: true }, res, next);
    assert.equal(next.errors.length, 1);
    assert.equal(next.errors[0]?.message, 'account create');
    assert.deepEqual(res.sent, []);
  });

  test('GET /health synchronous route remains synchronous and unwrapped', () => {
    const route = router.routes[2];
    const res = createMockRes();
    const next = createMockNext();
    const result = route.handler({ id: 'health' }, res, next);
    assert.equal(result, 'ok');
    assert.deepEqual(res.sent, ['ok']);
    assert.equal(next.errors.length, 0);
    assert.ok(!(result instanceof Promise), 'Synchronous route should not return a Promise');
  });

  test('GET /orders/:id succeeds and returns response value', async () => {
    const route = router.routes[3];
    const res = createMockRes();
    const next = createMockNext();
    const result = await route.handler({ id: 'ord-abc' }, res, next);
    assert.equal(result, 'ORD-ABC');
    assert.deepEqual(res.sent, ['ORD-ABC']);
    assert.equal(next.errors.length, 0);
  });

  test('GET /orders/:id forwards failure to next', async () => {
    const route = router.routes[3];
    const res = createMockRes();
    const next = createMockNext();
    await route.handler({ id: 'ord-abc', fail: true }, res, next);
    assert.equal(next.errors.length, 1);
    assert.equal(next.errors[0]?.message, 'order read');
    assert.deepEqual(res.sent, []);
  });

  test('DELETE /orders/:id succeeds and returns response value', async () => {
    const route = router.routes[4];
    const res = createMockRes();
    const next = createMockNext();
    const result = await route.handler({ id: 'ord-del' }, res, next);
    assert.equal(result, 'deleted:ord-del');
    assert.deepEqual(res.sent, ['deleted:ord-del']);
    assert.equal(next.errors.length, 0);
  });

  test('DELETE /orders/:id forwards failure to next', async () => {
    const route = router.routes[4];
    const res = createMockRes();
    const next = createMockNext();
    await route.handler({ id: 'ord-del', fail: true }, res, next);
    assert.equal(next.errors.length, 1);
    assert.equal(next.errors[0]?.message, 'order delete');
    assert.deepEqual(res.sent, []);
  });

  test('unrelated helper functions and audit API callbacks are not wrapped', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, { message: 'audit' });

    await assert.rejects(async () => {
      await unrelatedHelper();
    }, { message: 'helper' });
  });
});

