import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  return {
    send(value) {
      return value;
    }
  };
}

describe('Router async handlers regression tests', () => {
  const router = makeRouter();

  test('registration order and methods are preserved', () => {
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' }
      ]
    );
  });

  test('GET /accounts/:id handles success and preserves response', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    assert.ok(route);
    let nextCalled = false;
    const res = createMockRes();
    const result = await route.handler({ id: '123' }, res, (err) => {
      nextCalled = true;
    });
    assert.equal(result, 'account:123');
    assert.equal(nextCalled, false);
  });

  test('GET /accounts/:id forwards error to next when failing', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    assert.ok(route);
    let forwardedError = null;
    const res = createMockRes();
    await route.handler({ id: '123', fail: true }, res, (err) => {
      forwardedError = err;
    });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account read');
  });

  test('POST /accounts handles success and preserves response', async () => {
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    assert.ok(route);
    let nextCalled = false;
    const res = createMockRes();
    const result = await route.handler({ id: 'acc-456' }, res, (err) => {
      nextCalled = true;
    });
    assert.equal(result, 'created:acc-456');
    assert.equal(nextCalled, false);
  });

  test('POST /accounts forwards error to next when failing', async () => {
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    assert.ok(route);
    let forwardedError = null;
    const res = createMockRes();
    await route.handler({ id: 'acc-456', fail: true }, res, (err) => {
      forwardedError = err;
    });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account create');
  });

  test('GET /health synchronous route is preserved and unwrapped', () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
    assert.ok(route);
    let nextCalled = false;
    const res = createMockRes();
    const result = route.handler({ id: '' }, res, (err) => {
      nextCalled = true;
    });
    // Handler is synchronous: does not return a Promise
    assert.equal(result, 'ok');
    assert.equal(nextCalled, false);
    assert.equal(result instanceof Promise, false);
  });

  test('GET /orders/:id handles success and preserves response', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    assert.ok(route);
    let nextCalled = false;
    const res = createMockRes();
    const result = await route.handler({ id: 'order-789' }, res, (err) => {
      nextCalled = true;
    });
    assert.equal(result, 'ORDER-789');
    assert.equal(nextCalled, false);
  });

  test('GET /orders/:id forwards error to next when failing', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    assert.ok(route);
    let forwardedError = null;
    const res = createMockRes();
    await route.handler({ id: 'order-789', fail: true }, res, (err) => {
      forwardedError = err;
    });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order read');
  });

  test('DELETE /orders/:id handles success and preserves response', async () => {
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    assert.ok(route);
    let nextCalled = false;
    const res = createMockRes();
    const result = await route.handler({ id: 'order-789' }, res, (err) => {
      nextCalled = true;
    });
    assert.equal(result, 'deleted:order-789');
    assert.equal(nextCalled, false);
  });

  test('DELETE /orders/:id forwards error to next when failing', async () => {
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    assert.ok(route);
    let forwardedError = null;
    const res = createMockRes();
    await route.handler({ id: 'order-789', fail: true }, res, (err) => {
      forwardedError = err;
    });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order delete');
  });

  test('unrelated helper and audit API are not wrapped with withErrors', async () => {
    await assert.rejects(
      async () => {
        await auditCallback();
      },
      { name: 'Error', message: 'audit' }
    );

    await assert.rejects(
      async () => {
        await unrelatedHelper();
      },
      { name: 'Error', message: 'helper' }
    );
  });
});

