import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('RequestContext traceId migration and end-to-end propagation', () => {
  it('end-to-end propagation through handle', () => {
    const trace = 'trace-abc-123';
    const user = 'user-xyz-789';
    const job = {requestId: 'job-req-456', name: 'data-sync'};

    const outcome = handle(trace, user, job);

    // RequestContext field is traceId, no requestId property on context
    assert.equal(outcome.context.traceId, trace);
    assert.equal(outcome.context.userId, user);
    assert.equal('requestId' in outcome.context, false);

    // Headers propagate traceId under wire header 'x-request-id'
    assert.equal(outcome.headers['x-request-id'], trace);

    // Logging keeps wire/output key requestId with value traceId
    assert.equal(outcome.logs.requestId, trace);
    assert.equal(outcome.logs.userId, user);

    // Response body keeps wire/output key requestId with value traceId
    assert.equal(outcome.body.requestId, trace);

    // Payload received forked context with '/worker' suffix
    const payload = outcome.body.payload;
    assert.equal(payload.trace, `${trace}/worker`);
    assert.equal(payload.name, 'data-sync');

    // Unrelated Job identifier is preserved
    assert.equal(payload.requestId, job.requestId);
    assert.equal(payload.audit, `job:${job.requestId}`);
  });

  it('unrelated Job.requestId is distinct from context traceId', () => {
    const job = {requestId: 'unique-job-id-999', name: 'process-report'};
    const context = createContext('distinct-trace-id-111', 'operator');

    const result = describeJob(job, context);

    assert.equal(result.requestId, 'unique-job-id-999');
    assert.equal(result.trace, 'distinct-trace-id-111');
    assert.equal(result.audit, 'job:unique-job-id-999');
    assert.equal(result.name, 'process-report');
  });

  it('forkContext preserves non-mutation and appends suffixes', () => {
    const base = createContext('root-trace', 'admin');
    const child = forkContext(base, 'child');
    const grandchild = forkContext(child, 'grandchild');

    assert.equal(base.traceId, 'root-trace');
    assert.equal(child.traceId, 'root-trace/child');
    assert.equal(grandchild.traceId, 'root-trace/child/grandchild');
    assert.equal('requestId' in base, false);
    assert.equal('requestId' in child, false);
    assert.equal('requestId' in grandchild, false);
  });

  it('traceSummary preserves plugin consumers and returns expected output', () => {
    const context = createContext('plugin-trace', 'plugin-user');
    const summary = traceSummary(context);

    assert.equal(summary.length, 8);
    summary.forEach((item, index) => {
      assert.equal(item.requestId, 'plugin-trace');
      assert.equal(item.tag, `plugin${index}`);
      assert.equal(item.user, 'plugin-user');
    });
  });

  it('catalog RequestContext and requestId remain unchanged', () => {
    const catalogCtx = {requestId: 'cat-req-1', category: 'books'};
    const res = record0(catalogCtx);
    assert.equal(res.requestId, 'cat-req-1');
    assert.equal(res.category, 'books');
    assert.equal(res.label, 'record0:cat-req-1');
  });
});

