import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('end-to-end propagation from app entry point', () => {
  test('propagates traceId to all stages and preserves outputs', () => {
    const job = {requestId: 'job-456', name: 'sync-data'};
    const result = handle('trace-123', 'user-789', job);

    // RequestContext field is traceId, not requestId
    assert.equal(result.context.traceId, 'trace-123');
    assert.equal(result.context.userId, 'user-789');
    assert.equal('requestId' in result.context, false);

    // Middleware headers preserve wire key and receive traceId
    assert.equal(result.headers['x-request-id'], 'trace-123');

    // Logging preserves output keys and receives traceId
    assert.equal(result.logs.requestId, 'trace-123');
    assert.equal(result.logs.userId, 'user-789');

    // Response wire output key requestId receives traceId
    assert.equal(result.body.requestId, 'trace-123');

    // Worker payload receives forked context with suffix
    assert.equal(result.body.payload.trace, 'trace-123/worker');

    // Unrelated Job.requestId is preserved throughout
    assert.equal(result.body.payload.requestId, 'job-456');
    assert.equal(result.body.payload.name, 'sync-data');
    assert.equal(result.body.payload.audit, 'job:job-456');
  });
});

describe('context factory and non-mutation behavior', () => {
  test('createContext constructs RequestContext with traceId', () => {
    const ctx = createContext('trace-root', 'user-001');
    assert.equal(ctx.traceId, 'trace-root');
    assert.equal(ctx.userId, 'user-001');
    assert.equal('requestId' in ctx, false);
  });

  test('forkContext appends suffix and does not mutate parent context', () => {
    const parent = createContext('trace-root', 'user-001');
    const child = forkContext(parent, 'child-stage');

    assert.equal(parent.traceId, 'trace-root');
    assert.equal(child.traceId, 'trace-root/child-stage');
    assert.equal(child.userId, 'user-001');

    const grandchild = forkContext(child, 'sub-task');
    assert.equal(child.traceId, 'trace-root/child-stage');
    assert.equal(grandchild.traceId, 'trace-root/child-stage/sub-task');
  });
});

describe('unrelated Job identifier', () => {
  test('describeJob keeps job.requestId separate from context.traceId', () => {
    const job = {requestId: 'job-distinct-id', name: 'backup'};
    const ctx = createContext('trace-unrelated', 'admin');

    const desc = describeJob(job, ctx);
    assert.equal(desc.requestId, 'job-distinct-id');
    assert.equal(desc.trace, 'trace-unrelated');
    assert.equal(desc.audit, 'job:job-distinct-id');
    assert.equal(desc.name, 'backup');
  });

  test('auditLabel remains unchanged', () => {
    assert.equal(auditLabel('test-job-req'), 'job:test-job-req');
  });
});

describe('plugins and traceSummary', () => {
  test('traceSummary and plugin0..7 preserve output keys with traceId', () => {
    const ctx = createContext('trace-summary-test', 'user-plugin');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.equal(summary[i].requestId, 'trace-summary-test');
      assert.equal(summary[i].tag, `plugin${i}`);
      assert.equal(summary[i].user, 'user-plugin');
    }
  });
});

describe('catalog independence', () => {
  test('catalog RequestContext and requestId remain unchanged', () => {
    const catalogCtx = {requestId: 'cat-req-1', category: 'electronics'};
    const result = record0(catalogCtx);

    assert.equal(result.requestId, 'cat-req-1');
    assert.equal(result.category, 'electronics');
    assert.equal(result.label, 'record0:cat-req-1');
    assert.equal(audit0('cat-audit-9'), 'audit0:cat-audit-9');
  });
});

