export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

describe('taskLabel regression tests', () => {
  test('completed task receives [x] prefix', () => {
    assert.equal(taskLabel('review PR', true), '[x] review PR');
  });

  test('incomplete task keeps [ ] prefix', () => {
    assert.equal(taskLabel('review PR', false), '[ ] review PR');
  });

  test('preserves empty task name exactly', () => {
    assert.equal(taskLabel('', true), '[x] ');
    assert.equal(taskLabel('', false), '[ ] ');
  });

  test('preserves task name with leading and trailing spaces exactly', () => {
    assert.equal(taskLabel('  spaced item  ', true), '[x]   spaced item  ');
    assert.equal(taskLabel('  spaced item  ', false), '[ ]   spaced item  ');
  });

  test('preserves special characters and unicode', () => {
    assert.equal(taskLabel('🚀 Deploy v2.0 & check status', true), '[x] 🚀 Deploy v2.0 & check status');
    assert.equal(taskLabel('fix: handle null/undefined!', false), '[ ] fix: handle null/undefined!');
  });
});

