import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper, documentation} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  return {
    send(val) {
      return `sent:${val}`;
    }
  };
}

test('preserves route registration order, paths, and methods', () => {
  const router = makeRouter();
  const routes = router.routes;
  assert.equal(routes.length, 5);

  assert.deepEqual(
    routes.map(r => ({ method: r.method, path: r.path })),
    [
      { method: 'GET', path: '/accounts/:id' },
      { method: 'POST', path: '/accounts' },
      { method: 'GET', path: '/health' },
      { method: 'GET', path: '/orders/:id' },
      { method: 'DELETE', path: '/orders/:id' },
    ]
  );
});

test('GET /accounts/:id successful handling', async () => {
  const router = makeRouter();
  const route = router.routes[0];
  let nextCalled = false;
  const result = await route.handler(
    { id: '101' },
    createMockRes(),
    () => { nextCalled = true; }
  );
  assert.equal(result, 'sent:account:101');
  assert.equal(nextCalled, false);
});

test('GET /accounts/:id error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[0];
  let forwardedError = null;
  await route.handler(
    { id: '101', fail: true },
    createMockRes(),
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account read');
});

test('POST /accounts successful handling', async () => {
  const router = makeRouter();
  const route = router.routes[1];
  let nextCalled = false;
  const result = await route.handler(
    { id: '202' },
    createMockRes(),
    () => { nextCalled = true; }
  );
  assert.equal(result, 'sent:created:202');
  assert.equal(nextCalled, false);
});

test('POST /accounts error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[1];
  let forwardedError = null;
  await route.handler(
    { id: '202', fail: true },
    createMockRes(),
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account create');
});

test('GET /health synchronous route preserved', () => {
  const router = makeRouter();
  const route = router.routes[2];
  let nextCalled = false;
  const result = route.handler(
    { id: 'health' },
    createMockRes(),
    () => { nextCalled = true; }
  );
  assert.equal(result, 'sent:ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id successful handling', async () => {
  const router = makeRouter();
  const route = router.routes[3];
  let nextCalled = false;
  const result = await route.handler(
    { id: 'order-abc' },
    createMockRes(),
    () => { nextCalled = true; }
  );
  assert.equal(result, 'sent:ORDER-ABC');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[3];
  let forwardedError = null;
  await route.handler(
    { id: 'order-abc', fail: true },
    createMockRes(),
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order read');
});

test('DELETE /orders/:id successful handling', async () => {
  const router = makeRouter();
  const route = router.routes[4];
  let nextCalled = false;
  const result = await route.handler(
    { id: 'order-del-1' },
    createMockRes(),
    () => { nextCalled = true; }
  );
  assert.equal(result, 'sent:deleted:order-del-1');
  assert.equal(nextCalled, false);
});

test('DELETE /orders/:id error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[4];
  let forwardedError = null;
  await route.handler(
    { id: 'order-del-1', fail: true },
    createMockRes(),
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order delete');
});

test('unrelated helpers and callbacks are not wrapped', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");
  await assert.rejects(async () => { await unrelatedHelper(); }, /helper/);
  await assert.rejects(async () => { await auditCallback(); }, /audit/);
});

