import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  let sent = null;
  return {
    res: {
      send(val) {
        sent = val;
        return val;
      },
    },
    getSent: () => sent,
  };
}

function createMockNext() {
  const errors = [];
  return {
    next: (err) => {
      errors.push(err);
    },
    errors,
  };
}

describe('Router registration order and methods', () => {
  it('preserves registration order, methods, and paths', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);

    assert.equal(router.routes[0].method, 'GET');
    assert.equal(router.routes[0].path, '/accounts/:id');

    assert.equal(router.routes[1].method, 'POST');
    assert.equal(router.routes[1].path, '/accounts');

    assert.equal(router.routes[2].method, 'GET');
    assert.equal(router.routes[2].path, '/health');

    assert.equal(router.routes[3].method, 'GET');
    assert.equal(router.routes[3].path, '/orders/:id');

    assert.equal(router.routes[4].method, 'DELETE');
    assert.equal(router.routes[4].path, '/orders/:id');
  });
});

describe('GET /accounts/:id', () => {
  it('handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    const result = await route.handler({id: 'acc-1'}, res, next);
    assert.equal(result, 'account:acc-1');
    assert.equal(getSent(), 'account:acc-1');
    assert.equal(errors.length, 0);
  });

  it('catches and forwards failure to next', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    await route.handler({id: 'acc-1', fail: true}, res, next);
    assert.equal(getSent(), null);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account read');
  });
});

describe('POST /accounts', () => {
  it('handles success with named async function and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    const result = await route.handler({id: 'acc-2'}, res, next);
    assert.equal(result, 'created:acc-2');
    assert.equal(getSent(), 'created:acc-2');
    assert.equal(errors.length, 0);
  });

  it('catches and forwards failure to next', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    await route.handler({id: 'acc-2', fail: true}, res, next);
    assert.equal(getSent(), null);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account create');
  });
});

describe('GET /health (synchronous route)', () => {
  it('handles success without wrapping', () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    const result = route.handler({id: 'none'}, res, next);
    assert.equal(result, 'ok');
    assert.equal(getSent(), 'ok');
    assert.equal(errors.length, 0);
  });
});

describe('GET /orders/:id', () => {
  it('handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    const result = await route.handler({id: 'order-99'}, res, next);
    assert.equal(result, 'ORDER-99');
    assert.equal(getSent(), 'ORDER-99');
    assert.equal(errors.length, 0);
  });

  it('catches and forwards failure to next', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    await route.handler({id: 'order-99', fail: true}, res, next);
    assert.equal(getSent(), null);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order read');
  });
});

describe('DELETE /orders/:id', () => {
  it('handles success and returns response value', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    const result = await route.handler({id: 'order-101'}, res, next);
    assert.equal(result, 'deleted:order-101');
    assert.equal(getSent(), 'deleted:order-101');
    assert.equal(errors.length, 0);
  });

  it('catches and forwards failure to next', async () => {
    const router = makeRouter();
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    const {res, getSent} = createMockRes();
    const {next, errors} = createMockNext();

    await route.handler({id: 'order-101', fail: true}, res, next);
    assert.equal(getSent(), null);
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order delete');
  });
});

describe('Unrelated helpers and callbacks', () => {
  it('unrelatedHelper remains an unwrapped async function that throws', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, {name: 'Error', message: 'helper'});
  });

  it('auditCallback remains an unwrapped async callback that rejects', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, {name: 'Error', message: 'audit'});
  });
});

