import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {logFields} from '../src/logging.ts';
import {headers} from '../src/middleware.ts';
import {response} from '../src/response.ts';
import {work} from '../src/worker.ts';
import {traceSummary} from '../src/plugins/index.ts';

describe('RequestContext traceId migration and propagation', () => {
  it('propagates traceId end-to-end through handle without requestId on context', () => {
    const job = {requestId: 'job-101', name: 'indexer'};
    const result = handle('trace-root-123', 'user-456', job);

    // Context contains traceId and userId, no requestId
    assert.equal(result.context.traceId, 'trace-root-123');
    assert.equal(result.context.userId, 'user-456');
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.requestId, undefined);

    // Middleware headers preserve wire key with traceId value
    assert.deepEqual(result.headers, {'x-request-id': 'trace-root-123'});

    // Logging fields preserve wire key requestId with traceId value
    assert.deepEqual(result.logs, {
      requestId: 'trace-root-123',
      userId: 'user-456',
    });

    // Wire response preserves requestId key with traceId value
    assert.equal(result.body.requestId, 'trace-root-123');

    // Worker stage received forked context with worker suffix
    assert.deepEqual(result.body.payload, {
      requestId: 'job-101',
      trace: 'trace-root-123/worker',
      audit: 'job:job-101',
      name: 'indexer',
    });
  });

  it('forkContext extends traceId with suffix and preserves non-mutation', () => {
    const parent = createContext('trace-base', 'user-test');
    assert.equal(parent.traceId, 'trace-base');
    assert.equal(parent.userId, 'user-test');
    assert.equal('requestId' in parent, false);

    const child = forkContext(parent, 'child');
    // Parent context is not mutated
    assert.equal(parent.traceId, 'trace-base');
    // Child context has appended suffix
    assert.equal(child.traceId, 'trace-base/child');
    assert.equal(child.userId, 'user-test');
    assert.equal('requestId' in child, false);

    const grandchild = forkContext(child, 'grandchild');
    assert.equal(grandchild.traceId, 'trace-base/child/grandchild');
    assert.equal(child.traceId, 'trace-base/child');
    assert.equal(parent.traceId, 'trace-base');
  });

  it('preserves unrelated Job.requestId and audit label across execution stages', () => {
    const job = {requestId: 'job-789', name: 'export-data'};
    assert.equal(job.requestId, 'job-789');
    assert.equal(auditLabel(job.requestId), 'job:job-789');

    const ctx = createContext('trace-job-stage', 'user-stage');
    const described = describeJob(job, ctx);
    assert.equal(described.requestId, 'job-789');
    assert.equal(described.trace, 'trace-job-stage');
    assert.equal(described.audit, 'job:job-789');
    assert.equal(described.name, 'export-data');

    const worked = work(ctx, job);
    assert.equal(worked.requestId, 'job-789');
    assert.equal(worked.trace, 'trace-job-stage/worker');
    assert.equal(worked.audit, 'job:job-789');
    assert.equal(worked.name, 'export-data');
  });

  it('preserves traceSummary across all plugins with traceId', () => {
    const ctx = createContext('trace-plugins', 'user-plug');
    const summaries = traceSummary(ctx);

    assert.equal(summaries.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summaries[i], {
        requestId: 'trace-plugins',
        tag: `plugin${i}`,
        user: 'user-plug',
      });
    }
  });

  it('verifies individual components middleware, logging, and response', () => {
    const ctx = createContext('trace-comp', 'user-comp');

    assert.deepEqual(headers(ctx), {'x-request-id': 'trace-comp'});
    assert.deepEqual(logFields(ctx), {requestId: 'trace-comp', userId: 'user-comp'});
    assert.deepEqual(response(ctx, {ok: true}), {requestId: 'trace-comp', payload: {ok: true}});
  });
});

