import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('RequestContext traceId migration', () => {
  test('RequestContext has traceId and no requestId field', () => {
    const ctx = createContext('trace-abc', 'user-123');
    assert.equal(ctx.traceId, 'trace-abc');
    assert.equal(ctx.userId, 'user-123');
    assert.equal('requestId' in ctx, false);
  });

  test('forkContext appends suffix without mutating original context', () => {
    const parent = createContext('root-trace', 'user-456');
    const child = forkContext(parent, 'child-step');
    assert.equal(child.traceId, 'root-trace/child-step');
    assert.equal(child.userId, 'user-456');
    assert.equal(parent.traceId, 'root-trace');
    assert.equal('requestId' in child, false);
  });

  test('end-to-end propagation through handle stages', () => {
    const job = {requestId: 'job-999', name: 'batch-task'};
    const result = handle('trace-xyz', 'alice', job);

    // Context stage
    assert.equal(result.context.traceId, 'trace-xyz');
    assert.equal('requestId' in result.context, false);

    // Headers stage
    assert.equal(result.headers['x-request-id'], 'trace-xyz');

    // Logging stage preserves output key requestId with trace value
    assert.equal(result.logs.requestId, 'trace-xyz');
    assert.equal(result.logs.userId, 'alice');

    // Body stage preserves output key requestId with trace value
    assert.equal(result.body.requestId, 'trace-xyz');

    // Worker stage receives forked traceId and preserves unrelated Job.requestId
    assert.deepEqual(result.body.payload, {
      requestId: 'job-999',
      trace: 'trace-xyz/worker',
      audit: 'job:job-999',
      name: 'batch-task',
    });
  });

  test('unrelated Job.requestId is preserved in describeJob', () => {
    const ctx = createContext('trace-job-test', 'user-job');
    const job = {requestId: 'unique-job-id', name: 'export'};
    const description = describeJob(job, ctx);

    assert.equal(description.requestId, 'unique-job-id');
    assert.equal(description.trace, 'trace-job-test');
    assert.equal(description.audit, 'job:unique-job-id');
    assert.equal(description.name, 'export');
  });

  test('traceSummary preserves plugin outputs with traceId', () => {
    const ctx = createContext('trace-plugin-test', 'user-plugins');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < summary.length; i++) {
      assert.equal(summary[i].requestId, 'trace-plugin-test');
      assert.equal(summary[i].tag, `plugin${i}`);
      assert.equal(summary[i].user, 'user-plugins');
    }
  });

  test('catalog RequestContext with requestId remains isolated', () => {
    const catalogCtx = {requestId: 'cat-req-1', category: 'items'};
    const catalogResult = record0(catalogCtx);
    assert.equal(catalogResult.requestId, 'cat-req-1');
    assert.equal(catalogResult.category, 'items');
    assert.equal(catalogResult.label, 'record0:cat-req-1');
  });
});

